class MemoryCell:
    def __init__(self, cell_type='SRAM'):
        self.type = cell_type
        self.value = 0
        self.charge = 1.0 if cell_type == 'DRAM' else None
        self.leak_rate = 0.1 if cell_type == 'DRAM' else 0

    def read(self):
        if self.type == 'DRAM':
            # Sense the weak signal and restore
            self.charge = 1.0 if self.value else 0.0
        return self.value

    def write(self, value):
        self.value = value
        if self.type == 'DRAM':
            self.charge = 1.0 if value else 0.0

    def tick(self):
        if self.type == 'DRAM':
            self.charge -= self.leak_rate
            if self.charge < 0.3 and self.value == 1:
                # Data corruption due to leakage
                pass  # Would lose data in real scenario

    def refresh(self):
        if self.type == 'DRAM':
            self.charge = 1.0 if self.value else 0.0

class MemoryArray:
    def __init__(self, rows, cols, cell_type='SRAM'):
        self.rows = rows
        self.cols = cols
        self.cells = [[MemoryCell(cell_type) for _ in range(cols)] for _ in range(rows)]
        self.active_row = None
        self.cell_type = cell_type

    def activate_row(self, row_addr):
        self.active_row = row_addr
        # In real DRAM, this reads entire row into sense amps
        return sum(1 for c in self.cells[row_addr] if c.value)  # Dummy return

    def read(self, row, col):
        if self.cell_type == 'DRAM' and self.active_row != row:
            self.activate_row(row)
        return self.cells[row][col].read()

    def write(self, row, col, value):
        if self.cell_type == 'DRAM' and self.active_row != row:
            self.activate_row(row)
        self.cells[row][col].write(value)

    def refresh_all(self):
        for row in self.cells:
            for cell in row:
                cell.refresh()

# Test
sram = MemoryArray(4, 4, 'SRAM')
sram.write(0, 0, 1)
sram.write(1, 2, 1)
print(f'SRAM read: {sram.read(0, 0)}')

dram = MemoryArray(4, 4, 'DRAM')
dram.write(0, 0, 1)
print(f'DRAM before refresh: charge={dram.cells[0][0].charge:.2f}')
for _ in range(5):
    dram.cells[0][0].tick()
print(f'DRAM after leakage: charge={dram.cells[0][0].charge:.2f}')
dram.refresh_all()
print(f'DRAM after refresh: charge={dram.cells[0][0].charge:.2f}')
